def slug(i):return f'lesson-{i:03d}'

def svg_diagram(i,title,cat,seq):
    # Pure SVG; no downloaded tiles and no fictitious official map/architecture plans
    steps=seq
    esc=lambda x:html.escape(x,quote=True)
    blocks=[]
    for n,t in enumerate(steps):
        x=60+n*305
        blocks += [f'<rect x="{x}" y="120" rx="22" width="240" height="100" fill="{["#d9eee8","#e8f0f6","#f4e7dc"][n%3]}" stroke="#9bb5ae"/>',f'<text x="{x+120}" y="162" text-anchor="middle" font-size="19" font-weight="700" fill="#153b36">{esc(t)}</text>',f'<circle cx="{x+28}" cy="139" r="13" fill="#0c7769"/><text x="{x+28}" y="145" font-size="13" fill="white" text-anchor="middle">{n+1}</text>']
        if n<len(steps)-1:blocks +=[f'<path d="M{x+244} 170 H{x+289}" stroke="#607d75" stroke-width="3" fill="none" marker-end="url(#arrow)"/>']
    return ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1040 420" role="img" aria-label="'+esc(title)+' 개념도">'
     '<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#607d75"/></marker></defs>'
     '<rect width="1040" height="420" rx="28" fill="#f7faf8"/><text x="60" y="64" font-size="16" fill="#0c7769" font-weight="700">재개발 강실장 · 학습 개념도</text>'
     '<text x="60" y="99" font-size="23" font-weight="800" fill="#17372f">'+esc(title[:38])+'</text>'+''.join(blocks)+
     '<rect x="60" y="272" width="920" height="90" rx="16" fill="#e5edeb"/><text x="82" y="310" font-size="18" fill="#315e55">※ 공식 설계도면이나 개별 사건 판단이 아닌 교육용 도식입니다.</text>'
     '<text x="82" y="338" font-size="16" fill="#315e55">원문 법령·판례와 실제 고시를 확인하세요.</text></svg>')

